input.command:
foreach ($r in @("$HOME\.claude", "$HOME\.claude\skills", "$HOME\.claude\global-memory")) {
  Write-Output "=== $r"
  if (git -C $r status --porcelain) { git -C $r add -A; git -C $r commit -q -m "windows snapshot before sync" 2>&1 | Select-Object -Last 2 }
  $before = git -C $r rev-parse HEAD
  git -C $r pull --no-rebase --no-edit 2>&1 | Select-Object -Last 4
  $after = git -C $r rev-parse HEAD
  Write-Output "incoming: $(git -C $r rev-list --count --no-merges "$before..$after")"
  if ($before -ne $after) { git -C $r log -1 --format="newest: %h %ad %s" --date=short "$before..$after" --no-merges }
  git -C $r push 2>&1 | Select-Object -Last 1
  Write-Output "status: $(@(git -C $r status --porcelain).Where({$_}).Count) dirty, $(git -C $r rev-list --count '@{u}..HEAD') unpushed"
}

